H,W=len(grid),len(grid[0]); frames=[]
for color in set(sum(grid,[]))-{9}:
 for r0 in range(H):
  for c0 in range(W):
   if grid[r0][c0]!=color: continue
   for side in range(3,min(H-r0,W-c0)+1):
    r1,c1=r0+side-1,c0+side-1
    # perimeter is color, interior only background 9
    if all(grid[r][c]==color for r in range(r0,r1+1) for c in range(c0,c1+1) if r in (r0,r1) or c in (c0,c1)) and all(grid[r][c]==9 for r in range(r0+1,r1) for c in range(c0+1,c1)):
     frames.append((color,r0,c0,side))
print(frames)
out=[row[:] for row in grid]
for color,r,c,n in frames:
 val=2 if n%2==0 else 7
 for i in range(r+1,r+n-1):
  for j in range(c+1,c+n-1): out[i][j]=val
print('\n'.join(' '.join(map(str,r)) for r in out))
